func matchesString(c storage.EvaluationConstraint, v string) bool {
	switch c.Operator {
	case flipt.OpEmpty:
		return len(strings.TrimSpace(v)) == 0
	case flipt.OpNotEmpty:
		return len(strings.TrimSpace(v)) != 0
	}

	if v == "" {
		return false
	}

	value := c.Value

	switch c.Operator {
	case flipt.OpEQ:
		return value == v
	case flipt.OpNEQ:
		return value != v
	case flipt.OpPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case flipt.OpSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	case flipt.OpIsOneOf, flipt.OpIsNotOneOf:
		var values []string
		if err := json.Unmarshal([]byte(value), &values); err != nil || values == nil {
			return false
		}
		var items []json.RawMessage
		_ = json.Unmarshal([]byte(value), &items)
		for _, item := range items {
			if string(item) == "null" {
				return false
			}
		}
		for _, item := range values {
			if v == item {
				return c.Operator == flipt.OpIsOneOf
			}
		}
		return c.Operator == flipt.OpIsNotOneOf
	}

	return false
}

